Goal: the Go interface every model backend implements. Types only; nothing calls it yet.

Do: create runtime/engine/engine.go, package engine:
type Message struct { Role string `json:"role"`; Content string `json:"content,omitempty"`; ToolCalls []ToolCall `json:"tool_calls,omitempty"`; ToolCallID string `json:"tool_call_id,omitempty"` }
type ToolCall struct { ID string `json:"id"`; Name string `json:"name"`; Arguments json.RawMessage `json:"arguments"` }
type ToolSpec struct { Name string; Description string; Schema json.RawMessage }   // Schema is a JSON Schema object
type ChatRequest struct { Slot int; Messages []Message; Tools []ToolSpec; CachePrompt bool; MaxTokens int; Thinking bool }
type Chunk struct { Text string; Done bool; Message *Message; PromptTokens, OutputTokens int; Err error }   // the last chunk has Done true and the complete Message
type Stream interface { Recv() (Chunk, error); Close() error }   // Recv returns io.EOF after the Done chunk
type SlotState struct { ID int; Busy bool; Tokens int }
type ModelInfo struct { ID string; ContextTokens int; KVType string; Build string; ModelFile string; ModelBytes int64 }
func (m ModelInfo) Fingerprint() string   // hex sha256 of ID, ContextTokens, KVType, Build, ModelFile, ModelBytes joined with "|" ; first 16 hex chars
type SnapshotMeta struct { File string; Tokens int; Bytes int64; Seconds float64 }
type Caps struct { SlotSave, SleepWake, Priority, ExpertOffload, VariableTickCost bool }
type Engine interface {
  Info(ctx context.Context) (ModelInfo, error)
  Caps() Caps
  Slots(ctx context.Context) ([]SlotState, error)
  Chat(ctx context.Context, req ChatRequest) (Stream, error)
  SaveSlot(ctx context.Context, slot int, name string) (SnapshotMeta, error)
  RestoreSlot(ctx context.Context, slot int, name string) error
  EraseSlot(ctx context.Context, slot int) error
  Health(ctx context.Context) error
}
